:root {
  --motor-border: #01524F;

  --motor-fill-light: #EDF7F5;
  --motor-fill-middle: #D3E8E2;
  --motor-fill-base: #BDDBD4;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;

  background: transparent !important;
  pointer-events: none;
}

.motor-widget,
.motor-widget * {
  box-sizing: border-box;
}

.motor-widget {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  pointer-events: none;
  user-select: none;
  opacity: var(--w-opacity, 1);
}

.motor-button {
  position: absolute;
  left: 50%;
  top: 50%;

  display: block;
  width: var(--motor-width, 100%);
  height: var(--motor-height, 100%);

  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;

  appearance: none;
  border: none;
  background: transparent;

  transform: translate(-50%, -50%);

  pointer-events: none;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.motor-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  shape-rendering: geometricPrecision;
  pointer-events: none;
}

/* Todo el dibujo se hunde desde el mismo centro. */
.motor-drawing {
  transform-box: view-box;
  transform-origin: 50% 50%;
  transform: scale(1);
  pointer-events: none;
}

.motor-fill-light {
  stop-color: var(--motor-fill-light);
}

.motor-fill-middle {
  stop-color: var(--motor-fill-middle);
}

.motor-fill-base {
  stop-color: var(--motor-fill-base);
}

.motor-fill-light,
.motor-fill-middle,
.motor-fill-base {
  transition: stop-color 120ms ease;
}

.motor-body {
  fill: url("#motor-surface");
  stroke: var(--motor-border);
  stroke-width: 6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.motor-divider {
  fill: none;
  stroke: var(--motor-border);
  stroke-width: 3;
  stroke-linecap: round;
  opacity: 0.85;
}

.motor-lines {
  fill: none;
  stroke: var(--motor-border);
  stroke-width: 5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.motor-highlight,
.motor-shaft-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 2.5;
  stroke-linecap: round;
  opacity: 0.65;

  transition: opacity 120ms ease;
}

.motor-inner-shadow {
  fill: none;
  stroke: #01524F;
  stroke-width: 7;
  stroke-linecap: round;
  opacity: 0.12;

  transition: opacity 120ms ease;
}

.motor-pressed-shadow {
  fill: none;
  stroke: #01524F;
  stroke-width: 8;
  stroke-linecap: round;
  opacity: 0;

  transition: opacity 120ms ease;
}

/* Solo la silueta del motor recibe el puntero dentro del widget. */
.motor-hit-area {
  fill: transparent;
  stroke: transparent;
  stroke-width: 6;
  stroke-linejoin: round;
  pointer-events: all;
  cursor: pointer;
}

@media (hover: hover) {
  .motor-button:hover {
    --motor-fill-light: #F5FCFA;
    --motor-fill-middle: #DDEFE9;
    --motor-fill-base: #C8E3DB;
  }

  .motor-button:hover .motor-highlight,
  .motor-button:hover .motor-shaft-highlight {
    opacity: 0.85;
  }
}

/* Se mantiene presionado hasta soltar el botón. */
.motor-button:active {
  --motor-fill-light: #D5E8E2;
  --motor-fill-middle: #C9E1D9;
  --motor-fill-base: #B9D8CE;
}

.motor-button:active .motor-drawing {
  transform: scale(0.98);
}

.motor-button:active .motor-highlight,
.motor-button:active .motor-shaft-highlight {
  opacity: 0.25;
}

.motor-button:active .motor-pressed-shadow {
  opacity: 0.22;
}

.motor-button:active .motor-inner-shadow {
  opacity: 0.06;
}

.motor-button:focus-visible {
  outline: none;
}

.motor-button:focus-visible .motor-body {
  stroke-width: 8;
}

@media (prefers-reduced-motion: reduce) {
  .motor-fill-light,
  .motor-fill-middle,
  .motor-fill-base,
  .motor-highlight,
  .motor-shaft-highlight,
  .motor-inner-shadow,
  .motor-pressed-shadow {
    transition: none;
  }
}

