"use strict";

(function () {
  const BASE_WIDTH = 220;
  const BASE_HEIGHT = 150;

  let container = null;
  let resizeObserver = null;
  let pendingFrame = null;

  function resizeLayout() {
    if (!container) return;

    const width = container.clientWidth;
    const height = container.clientHeight;

    if (width <= 0 || height <= 0) return;

    /*
     * Escala proporcionalmente para conservar
     * la forma del símbolo del motor.
     */
    const scale = Math.min(
      width / BASE_WIDTH,
      height / BASE_HEIGHT
    );

    container.style.setProperty(
      "--motor-width",
      (BASE_WIDTH * scale) + "px"
    );

    container.style.setProperty(
      "--motor-height",
      (BASE_HEIGHT * scale) + "px"
    );
  }

  function scheduleLayout() {
    if (pendingFrame !== null) return;

    pendingFrame = requestAnimationFrame(function () {
      pendingFrame = null;
      resizeLayout();
    });
  }

  window.onWidgetUpdate = function () {
    scheduleLayout();
  };

  function initialize() {
    container = document.querySelector(".motor-widget");

    if (!container) return;

    resizeLayout();

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(scheduleLayout);
      resizeObserver.observe(container);
    } else {
      window.addEventListener("resize", scheduleLayout);
    }

    /*
     * Sin texto ni variables del PLC.
     * Hover y pulsación gestionados mediante CSS.
     * No se configura ninguna acción de control al hacer clic.
     *
     * La silueta interactiva corresponde al botón interno;
     * no modifica el contenedor externo del software.
     */
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
